import{at as e,it as t,n,vt as r}from"./chunks/framework.DkF-bNzI.js";var i=JSON.parse(`{"title":"Comparison","description":"","frontmatter":{},"headers":[],"relativePath":"comparison.md","filePath":"comparison.md","lastUpdated":1795647357000}`),a={name:`comparison.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="comparison" tabindex="-1">Comparison <a class="header-anchor" href="#comparison" aria-label="Permalink to “Comparison”">​</a></h1><p>Two groups get mixed together. The first tests the methods a class already has. The second only builds instances. Versions were current in November 2026. A later release can move a cell. This page does not repeat the coverage numbers from the 2016 comparison. Those were measured with JaCoCo 0.7.7 on four generated classes.</p><h2 id="libraries-that-test-the-methods" tabindex="-1">Libraries that test the methods <a class="header-anchor" href="#libraries-that-test-the-methods" aria-label="Permalink to “Libraries that test the methods”">​</a></h2><table tabindex="0"><thead><tr><th></th><th>pojo-tester</th><th>EqualsVerifier</th><th>OpenPojo</th><th>MeanBean</th><th>JavaBean Tester</th><th>bean-matchers</th></tr></thead><tbody><tr><td>Coordinates</td><td><code>pl.pojo:pojo-tester</code></td><td><code>nl.jqno.equalsverifier:equalsverifier</code></td><td><code>com.openpojo:openpojo</code></td><td><code>com.github.meanbeanlib:meanbean</code></td><td><code>com.github.hazendaz:javabean-tester</code></td><td><code>com.google.code.bean-matchers:bean-matchers</code></td></tr><tr><td>Version</td><td><code>0.8.0-SNAPSHOT</code>, last release <code>0.7.6</code> (2017)</td><td><code>4.5.2</code> (August 2026)</td><td><code>0.9.1</code></td><td><code>3.0.0-M9</code> (2020)</td><td><code>2.12.2</code></td><td><code>0.14</code></td></tr><tr><td>License</td><td>LGPL-3.0</td><td>Apache-2.0</td><td>Apache-2.0</td><td>Apache-2.0</td><td>Apache-2.0</td><td>BSD-3-Clause</td></tr><tr><td>Java</td><td>bytecode 8</td><td>8, with newer lines</td><td>8 and newer</td><td>8</td><td>17</td><td>8</td></tr><tr><td><code>equals</code></td><td>yes</td><td>yes, the contract</td><td>only through its own <code>BusinessIdentity</code></td><td>yes</td><td>yes</td><td>yes</td></tr><tr><td><code>hashCode</code></td><td>yes</td><td>yes, the contract</td><td>only through <code>BusinessIdentity</code></td><td>yes</td><td>yes</td><td>yes</td></tr><tr><td><code>toString</code></td><td>yes</td><td>no</td><td>only through <code>BusinessIdentity</code></td><td>yes, in the 3.x line</td><td>yes</td><td>yes</td></tr><tr><td>getters and setters</td><td>yes</td><td>no</td><td>yes</td><td>yes</td><td>yes</td><td>yes</td></tr><tr><td>constructors</td><td>yes</td><td>no</td><td>no</td><td>no</td><td>yes</td><td>a no-args constructor</td></tr><tr><td>Production code stays untouched</td><td>yes</td><td>yes</td><td>no, for equals</td><td>yes</td><td>yes</td><td>yes</td></tr></tbody></table><p><strong>EqualsVerifier</strong> is the library to use when the only question is whether <code>equals</code> and <code>hashCode</code> meet the contract. It is strict about symmetry, inheritance, significant fields and the usual shortcuts, and it understands records. It does not call getters or setters. pojo-tester is not a substitute for that check. Use both when a class has a hand-written <code>equals</code> and also has getters.</p><p><strong>OpenPojo</strong> validates structure with rules, such as <code>SetterMustExistRule</code>, and can test getters and setters. Its <code>equals</code>, <code>hashCode</code> and <code>toString</code> support expects the class to delegate to <code>BusinessIdentity</code> and to mark fields with <code>@BusinessKey</code>. A class that already has its own implementations is not what that tester runs.</p><p><strong>MeanBean</strong> tests getters, setters, <code>equals</code> and <code>hashCode</code>. The original 2.x line is the one the 2016 page compared. The 3.x line, published as milestones through <code>3.0.0-M9</code>, adds <code>toString</code>, fluent setters and a package scan. There is no stable 3.0.0.</p><p><strong>JavaBean Tester</strong> covers constructors, getters, setters, <code>equals</code>, <code>hashCode</code>, <code>toString</code> and <code>Serializable</code>. It requires Java 17, so it is not an option for a Java 8 test suite.</p><p><strong>bean-matchers</strong> expresses the same checks as Hamcrest matchers, including a no-args constructor. The last release is <code>0.14</code>. The project is not maintained.</p><p>pojo-tester runs the six testers against the methods the class already has. It does not ask for an annotation, and one assertion can also select fields, a constructor, a supplier and a prefix.</p><p>The 2016 page also listed SmartUnit, testUtils and testUtil. They are not maintained and are not in the table.</p><h2 id="libraries-that-only-build-or-compare-objects" tabindex="-1">Libraries that only build or compare objects <a class="header-anchor" href="#libraries-that-only-build-or-compare-objects" aria-label="Permalink to “Libraries that only build or compare objects”">​</a></h2><p>These do not check that <code>equals</code>, a getter or a constructor is implemented correctly. They are listed because they are what people reach for when they search for a POJO test library.</p><table tabindex="0"><thead><tr><th>Library</th><th>Version</th><th>What it actually does</th></tr></thead><tbody><tr><td><a href="https://www.instancio.org/" target="_blank" rel="noreferrer">Instancio</a> <code>org.instancio:instancio-junit</code></td><td>6.2.2</td><td>Fills an object, including nested values, with reproducible random data.</td></tr><tr><td><a href="https://github.com/j-easy/easy-random" target="_blank" rel="noreferrer">Easy Random</a> <code>org.jeasy:easy-random-core</code></td><td>5.0.0</td><td>Fills an object. The last release is 5.0.0.</td></tr><tr><td><a href="https://github.com/mtedone/podam" target="_blank" rel="noreferrer">PODAM</a> <code>uk.co.jemos.podam:podam</code></td><td>8.0.2.RELEASE</td><td>Fills an object from a policy.</td></tr><tr><td><a href="https://assertj.github.io/doc/" target="_blank" rel="noreferrer">AssertJ</a> <code>org.assertj:assertj-core</code></td><td>3.27.7</td><td><code>usingRecursiveComparison()</code> walks two instances field by field. It does not call the class&#39;s <code>equals</code>, and it does not check a getter against its field. 4.0 is a Java 17 milestone.</td></tr><tr><td><a href="https://github.com/keepcosmos/beanmother" target="_blank" rel="noreferrer">Beanmother</a> <code>io.beanmother:beanmother-core</code></td><td>0.9.0</td><td>Builds objects from YAML fixtures. Not maintained.</td></tr><tr><td>Unitils <code>org.unitils:unitils-core</code></td><td>3.4.6 (2016)</td><td><code>ReflectionAssert</code> compares two instances. Not maintained.</td></tr></tbody></table>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};